{
  "measurement_needs": [
    "Temperature- and shear-dependent melt viscosity and viscoelastic behavior",
    "Thermal phase transitions (melting temperature, glass transition, and crystallization)",
    "Thermal stability and decomposition profile at extrusion temperatures"
  ],
  "objective_met": true,
  "recommendations": [
    {
      "instrument_id": "EQ21",
      "role": "primary",
      "technique": "Rotational rheometry / melt rheology",
      "why": "It directly measures complex viscosity, storage modulus, and loss modulus as a function of temperature, shear rate, and time, revealing whether the polymer experiences incomplete melting, shear-thickening, or thermally induced crosslinking.",
      "accessories_to_confirm": ["Parallel plate or cone-and-plate geometries suitable for polymer melts", "Disposable test plates (if irreversible crosslinking or degradation is suspected)"]
    },
    {
      "instrument_id": "EQ18",
      "role": "supplementary",
      "technique": "Differential scanning calorimetry (DSC)",
      "why": "It determines whether the extrusion temperature is above the actual melting point or if exothermic reaction peaks (such as curing or crosslinking) occur at that processing temperature.",
      "accessories_to_confirm": ["Tzero aluminum pans and hermetic lids", "Sample crimper"]
    },
    {
      "instrument_id": "EQ17",
      "role": "supplementary",
      "technique": "Thermogravimetric analysis (TGA)",
      "why": "It assesses whether mass loss, plasticizer volatilization, or thermal degradation occurs at the extrusion temperature, which could drastically increase viscosity.",
      "accessories_to_confirm": ["Platinum or ceramic sample pans"]
    }
  ],
  "not_available": [
    {
      "technique": "High-pressure capillary rheometry",
      "why_useful": "Extrusion typically involves shear rates (>1000 s⁻¹) higher than those achievable on standard rotational rheometers, making capillary rheometry ideal for exact extrusion conditions."
    },
    {
      "technique": "Gel permeation chromatography / size-exclusion chromatography (GPC/SEC)",
      "why_useful": "GPC would determine if the polymer batch has an unexpectedly high molecular weight or broad molecular weight distribution that raises melt viscosity."
    }
  ],
  "clarifying_question": null,
  "summary": "To understand why your polymer remains unexpectedly viscous, temperature-resolved melt rheometry on the Discovery HR20 (EQ21) can directly evaluate flow and viscoelastic properties under heat. Supplementary DSC (EQ18) and TGA (EQ17) will help determine whether incomplete melting, crystallization, thermally induced crosslinking, or volatilization is the underlying cause."
}

{
  "measurement_needs": [
    "Compressive stress-strain response",
    "Compressive stiffness (modulus) of a porous polymer scaffold"
  ],
  "objective_met": true,
  "recommendations": [
    {
      "instrument_id": "EQ15",
      "role": "primary",
      "technique": "Uniaxial compression testing",
      "why": "Applies controlled compressive displacement to measure force-displacement behavior and determine the compressive modulus of the scaffold.",
      "accessories_to_confirm": [
        "Upper and lower compression platens",
        "Appropriately scaled load cell suited for compliant or porous polymer specimens (e.g., 10 N to 500 N)"
      ]
    },
    {
      "instrument_id": "EQ21",
      "role": "supplementary",
      "technique": "Dynamic mechanical analysis / axial compression",
      "why": "Provides dynamic or small-scale axial compressive testing to evaluate viscoelastic properties if the scaffold is exceptionally soft or hydrogel-based.",
      "accessories_to_confirm": [
        "Parallel-plate compression geometry",
        "Axial DMA software/testing mode"
      ]
    }
  ],
  "not_available": [
    {
      "technique": "Micro-computed tomography (micro-CT)",
      "why_useful": "Enables non-destructive 3D quantification of pore size, interconnectivity, and porosity to correlate structural architecture with mechanical stiffness."
    }
  ],
  "clarifying_question": null,
  "summary": "The Instron 5967 universal testing system (EQ15) is the primary instrument for performing quasistatic uniaxial compression to determine compressive stiffness. If your scaffold is very soft or viscoelastic, the HR20 hybrid rheometer (EQ21) can serve as a supplementary tool for small-strain compressive or dynamic mechanical analysis. Confirm that appropriate compression platens and a low-force load cell are available on the Instron for your scaffold's expected stiffness range."
}

{
  "measurement_needs": [
    "Non-destructive 3D visualization and quantification of internal pore morphology, pore distribution, and connectivity"
  ],
  "objective_met": false,
  "recommendations": [
    {
      "instrument_id": "EQ08",
      "role": "supplementary",
      "technique": "Multiphoton / confocal laser scanning microscopy (3D optical sectioning)",
      "why": "It can provide non-destructive 3D imaging of internal pore architecture without physical slicing, but it requires an optically transparent or fluorescently labeled matrix and is limited by optical penetration depth (typically up to several hundred micrometers).",
      "accessories_to_confirm": [
        "Long working distance or dipping objectives",
        "Appropriate excitation laser lines and detectors (e.g., reflection mode or multiphoton NDDs)"
      ]
    },
    {
      "instrument_id": "EQ07",
      "role": "supplementary",
      "technique": "Confocal laser scanning microscopy (3D optical sectioning)",
      "why": "It allows optical cross-sectioning and 3D reconstruction of porous networks near the surface or within optically cleared specimens.",
      "accessories_to_confirm": [
        "Suitable objectives for sample thickness and working distance",
        "Reflected light or fluorescence detector settings"
      ]
    }
  ],
  "not_available": [
    {
      "technique": "X-ray micro-computed tomography (micro-CT)",
      "why_useful": "Micro-CT is the gold standard for non-destructive 3D imaging of internal pores, pore size distribution, and interconnectivity in thick, opaque solid specimens."
    }
  ],
  "clarifying_question": null,
  "summary": "No listed instrument can perform standard non-destructive 3D internal imaging on general or opaque porous specimens; the ideal technique for this is X-ray micro-computed tomography (micro-CT), which is not available on campus. If your specimen is optically translucent, cleared, or fluorescently labeled, confocal or multiphoton microscopes (EQ07, EQ08) may offer supplementary non-destructive 3D optical sectioning, though optical penetration depth is strictly limited."
}

{
  "measurement_needs": [
    "non-destructive 3D internal structure imaging",
    "internal porosity and pore architecture"
  ],
  "objective_met": false,
  "recommendations": [
    {
      "instrument_id": "EQ08",
      "role": "supplementary",
      "technique_id": "multiphoton_microscopy",
      "property_id": "internal_3d_structure",
      "technique": "Multiphoton microscopy",
      "why": "It can perform non-destructive optical sectioning up to several hundred micrometres below the surface, but it requires the specimen to be fluorescent or SHG-active (such as collagen) and cannot image through opaque materials.",
      "accessories_to_confirm": [
        "tunable infrared multiphoton laser",
        "non-descanned detectors for deep imaging",
        "water-dipping objective with long working distance"
      ]
    },
    {
      "instrument_id": "EQ07",
      "role": "supplementary",
      "technique_id": "confocal_microscopy",
      "property_id": "internal_3d_structure",
      "technique": "Confocal laser scanning microscopy",
      "why": "It enables non-destructive 3D optical sectioning of internal structure, but depth penetration is limited to approximately 100 µm and requires optical transparency or fluorescent labeling.",
      "accessories_to_confirm": [
        "laser lines and detectors matching the fluorophores",
        "objectives of suitable magnification and working distance"
      ]
    }
  ],
  "not_available": [
    {
      "technique_id": "micro_computed_tomography",
      "technique": "X-ray micro-computed tomography (micro-CT)",
      "why_useful": "Micro-CT is the standard non-destructive method for mapping 3D internal architecture, pore interconnectivity, and porosity across entire bulk, opaque specimens."
    }
  ],
  "clarifying_question": null,
  "summary": "No listed instrument can perform complete, non-destructive volumetric internal structure imaging of bulk porous specimens. The standard method for this analysis is X-ray micro-computed tomography (micro-CT), which is not available on the current equipment list. However, if your sample is optically transparent or fluorescently labeled, upright multiphoton microscopy (EQ08) or inverted confocal microscopy (EQ07) can provide supplementary optical sectioning within the first 100 to several hundred micrometres of the surface."
}

